1	// The auto-merge policy engine (tasks-dispatch DESIGN §16.11): may THIS diff land
2	// without a person? A task declares `automerge` — `'nothing'`, `'anything'`,
3	// or a list of named diff classes — and this module turns that declaration plus
4	// the branch's actual diff into a verdict. The call is arithmetic over the diff,
5	// never the session's opinion of its own work: a run cannot talk its way past a
6	// text comparison (the narrow-diff posture, generalized).
7	//
8	// WHAT A POLICY IS FOR. A policy is its author's PREDICTION of the change's
9	// shape — the folders and the kinds of file a request should touch. When the
10	// diff sits inside the prediction, nobody reads it: the code is out the door and
11	// working, and a later PR can improve it. When the diff misses the prediction,
12	// the PR parks for a person, and that park is the mechanism's purpose rather
13	// than its failure. The reviewer here is not checking that the code is perfect;
14	// they are checking the wagon is on the trail — that nothing irreversible
15	// slipped through, and that the change's footprint matches its ask (a wide diff
16	// for a small request is a lesson in separation of concerns, not a defect). So a
17	// policy is written narrow, from the predicted folders, and is never widened to
18	// fit the diff that arrived.
19	//
20	// THE VOCABULARY IS EXTENSIBLE AS DATA. Built-in diff classes live here; a pack
21	// adds its own by shipping a `merge-rules.json` beside its `pack.mjs` — named
22	// path/kind/edit-shape matchers, validated at load, colliding loudly. A policy
23	// then names any rule, built-in or declared, plus the inline `under:<dir>` scope
24	// that carries its own argument, and an unknown name FAILS CLOSED: a policy this
25	// code cannot fully resolve authorizes nothing.
26	//
27	// A LIST IS A UNION, `&&` IS THE INTERSECTION. Listing two terms widens — each
28	// changed file need only be covered by one of them — so the way to say "docs,
29	// but only under this folder" is one `&&` term, never two list entries.
30	//
31	// POLICY SEMANTICS, in evaluation order:
32	//   - `'nothing'`  — never mergeable. `'anything'` — mergeable (the repo's own
33	//     delivery settings still apply downstream, land-pr.mjs).
34	//   - a LIST mixes allow terms and `reject:<name>` terms. A reject matching any
35	//     changed file vetoes the whole diff; otherwise every changed file must be
36	//     covered by some allow term (first listed match wins), and every matched
37	//     rule's whole-diff constraint (e.g. "one code directory") must hold. A list
38	//     with no allow term is an authoring error, not "anything except" — spell
39	//     that as `['anything', 'reject:<name>']`.
40	//   - THE SELF-WIDENING GUARD: under a list policy, a change to the files that
41	//     define policies (`merge-rules.json`, `tasks/<name>/task.json`, this module,
42	//     its work-scope gate) is never coverable unless it is comment-only — a run
43	//     must not be able to grant itself a wider authorization than it started
44	//     with. Only the plain `'anything'` (the trusted lane: the vendored-mount
45	//     converge) can land such a change.
46	//
47	// Two judging surfaces read one resolution path: the landing lane's CLI below
48	// (what the worker doc tells a run to execute before it may merge), and the
49	// `automerge-policy-scope` work check beside this file, which re-evaluates the
50	// same verdict over a branch that stamped the arming trailer.
51	
52	import path from 'node:path';
53	import { readFileSync, existsSync } from 'node:fs';
54	import { execFileSync } from 'node:child_process';
55	import { COMMENT_CHECKABLE, commentOnly } from '../../engine/checks/helpers/code-scanning.mjs';
56	import { FILE_CLASSES } from '../../engine/checks/helpers/pattern-rules.mjs';
57	import { isActive } from '../../engine/pack_loader/pack-registry.mjs';
58	
59	export { COMMENT_CHECKABLE, commentOnly };
60	
61	export const POLICY_NOTHING = 'nothing';
62	export const POLICY_ANYTHING = 'anything';
63	
64	// The commit-message trailer a run stamps when it intends to land its own PR
65	// under a granular policy — what makes the work-scope gate self-gating: no
66	// trailer, no armed auto-merge, nothing to judge. The policy expression is the
67	// string form below (`a;b;reject:c`).
68	export const AUTOMERGE_TRAILER = 'Claudinite-Automerge-Policy';
69	export const AUTOMERGE_TRAILER_RE = /^Claudinite-Automerge-Policy:[ \t]*(\S+)[ \t]*$/m;
70	
71	// --- path classification (shared with narrow-diff.mjs, which re-exports it) ---
72	
73	const DOC_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.rst']);
74	
75	const TEST_DIRS = new Set(['test', 'tests', '__tests__', 'spec', 'specs', 'fixtures', 'testdata']);
76	
77	// A path's kind, from the path alone: 'doc', 'test', or 'code'. Directory names
78	// are matched on whole segments (`tests/`), never on substrings, so `latest/` is
79	// not a test directory; file names are matched on the conventions every ecosystem
80	// here shares.
81	export function classifyPath(file) {
82	  const segments = file.split('/');
83	  const name = segments[segments.length - 1];
84	  if (segments.slice(0, -1).some((seg) => TEST_DIRS.has(seg) || seg.endsWith('-tests') || seg.endsWith('_tests'))) return 'test';
85	  if (/(^|[.\-_])(test|tests|spec)[.\-_]/i.test(name) || /^test_/i.test(name)) return 'test';
86	  if (DOC_EXTENSIONS.has(path.extname(name).toLowerCase())) return 'doc';
87	  return 'code';
88	}
89	
90	// --- diff entries -------------------------------------------------------------
91	
92	// One changed file with both contents: null `before` = added, null `after` =
93	// deleted. Everything below judges these, so a caller with another diff source
94	// (the work-scope context) builds the same shape.
95	export const changeKindOf = ({ before, after }) =>
96	  (before == null ? 'added' : after == null ? 'deleted' : 'modified');
97	
98	// Only line removals (and nothing else): the after-lines are an ordered
99	// subsequence of the before-lines. Deliberately order-preserving — a reorder is
100	// an edit, not a removal — and a whole-file deletion is every line removed.
101	export function removalsOnly(before, after) {
102	  return shrinkOnly(before, after, (line, original) => line === original);
103	}
104	
105	// Removals, plus in-line TRIMS: every surviving line either equals a line it
106	// replaces or is a character-subsequence of one — a line cut in half, a word
107	// struck from its middle, a truncation closed with a period the original
108	// already held. What can never pass is growth: no new line, and no character a
109	// replaced line did not already carry in order. The alignment is greedy and
110	// backtrack-free, so a pathological reshuffle can read as not-a-trim — that
111	// end fails safe (the diff parks for review).
112	export function trimsOnly(before, after) {
113	  return shrinkOnly(before, after, isCharSubsequence);
114	}
115	
116	function shrinkOnly(before, after, lineSatisfies) {
117	  if (after == null) return true;
118	  if (before == null) return false;
119	  const from = before.split('\n');
120	  const to = after.split('\n');
121	  let i = 0;
122	  for (const line of to) {
123	    while (i < from.length && !lineSatisfies(line, from[i])) i += 1;
124	    if (i === from.length) return false;
125	    i += 1;
126	  }
127	  return true;
128	}
129	
130	function isCharSubsequence(needle, hay) {
131	  let i = 0;
132	  for (const c of needle) {
133	    i = hay.indexOf(c, i);
134	    if (i === -1) return false;
135	    i += 1;
136	  }
137	  return true;
138	}
139	
140	const isCommentOnlyChange = (e) => changeKindOf(e) === 'modified' && commentOnly(e.file, e.before, e.after);
141	
